__NUXT_JSONP__("/tw/how-to-apply", {data:[{details:{slug:"tw",pageTitle:"您計畫申請什麼簽證? | Mentor Language Institute",pageDescription:"請從下方選擇您的簽證",title:"您計畫申請什麼簽證?",image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fvisa.jpg",category:[{title:"請從下方選擇您的簽證:",btn_visa:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fvisa_btn-tw.png",link:"\u002Ftw\u002Fhow-to-apply\u002Fstudent-visa-f1"},btn_others:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fothers_btn-tw.png",link:"\u002Ftw\u002Fhow-to-apply\u002Fothers"}}],content:{subtitle:"有其它的問題嗎?",description:["基本上，您需要一個學生簽證才能以長期學生身分待在美國。如果您不知道您是否需要簽證，請聯絡我們。我們有八國語言的客服。"],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fcontact-us-tw.png",link:"\u002Ftw\u002Fcontact"}},dir:"\u002Fhow-to-apply",path:"\u002Fhow-to-apply\u002Ftw",extension:".json",createdAt:"2026-10-22T16:31:29.664Z",updatedAt:"2025-05-26T12:06:27.792Z"}}],fetch:{},mutations:void 0});